<?php
use GhoroaHat\Rewards\{DB,Settings,Membership,Orders,Leaderboard,Rewards};
add_filter('pre_wp_mail','__return_true');global $wpdb,$ghr_competition_count;$ghr_competition_count=0;$before=Settings::all();$run='monthly'.bin2hex(random_bytes(4));
function competition_check($a,$b,$message){global $ghr_competition_count;++$ghr_competition_count;if($a!==$b){throw new RuntimeException($message.': '.var_export($a,true).' != '.var_export($b,true));}echo "PASS $message\n";}
try{
Settings::save(array('historical_rewards'=>true,'referral_approval'=>false,'hold_days'=>0,'repeat_referrals'=>true,'bonus_products'=>array(),'excluded_products'=>array(),'excluded_categories'=>array()));
$month=(new DateTimeImmutable('first day of last month',wp_timezone()))->format('Y-m');$date=(new DateTimeImmutable($month.'-10 12:00:00',wp_timezone()))->getTimestamp();$users=array();for($i=0;$i<8;$i++){$u=wp_insert_user(array('user_login'=>$run.$i,'user_email'=>$run.$i.'@example.org','user_pass'=>wp_generate_password()));Membership::enroll($u);DB::update(DB::table('memberships'),array('status'=>'active','email_verified_at'=>DB::now(),'activated_at'=>DB::now(),'public_consent'=>1),array('user_id'=>$u));$users[]=$u;}
$p=new WC_Product_Simple();$p->set_name('Monthly fixture');$p->set_regular_price('1000');$p->set_tax_status('none');$p->save();
foreach($users as $i=>$u){$o=wc_create_order(array('customer_id'=>$u));$o->add_product($p,1);$o->set_billing_email(get_userdata($u)->user_email);$o->set_date_created($date);$o->set_date_completed($date);$o->calculate_totals();$o->update_status('completed');$o->set_date_completed($date);$o->save();Orders::reconcile($o->get_id());}
for($i=0;$i<2;$i++){$o=wc_create_order(array('customer_id'=>$users[$i+4]));$o->add_product($p,1);$o->set_billing_email(get_userdata($users[$i+4])->user_email);$o->update_meta_data('_ghr_referrer',$users[$i+2]);$o->set_date_created($date+3600);$o->set_date_completed($date+3600);$o->calculate_totals();$o->update_status('completed');$o->set_date_completed($date);$o->save();Orders::reconcile($o->get_id());}
Leaderboard::prepare($month);$fresh=$wpdb->get_row($wpdb->prepare('SELECT personal,seeds FROM '.DB::table('monthly_scores').' WHERE month=%s AND user_id=%d ORDER BY id DESC LIMIT 1',$month,$users[0]),ARRAY_A);competition_check((int)$fresh['personal'],100000,'Fresh backdated order enters the correct calendar month');competition_check((int)$fresh['seeds'],10,'Fresh monthly personal Seeds aggregate');competition_check(count(Leaderboard::live($month,'regular',100))>=8,true,'Monthly qualifying personal purchases aggregated');competition_check(count(Leaderboard::live($month,'referrals',100))>=2,true,'Monthly qualifying referral conversions aggregated');
foreach(array('regular','referrals','seeds')as$category){foreach(array('top_prize','magic_box')as$award){$def=Rewards::definition(array('name'=>'Monthly '.$category.' '.$award,'type'=>'gift','stock'=>1,'config'=>array()));Rewards::campaign(array('name'=>$run.$category.$award,'month'=>$month,'category'=>$category.':'.$award,'definition_id'=>$def,'capacity'=>1));}}
$id=Leaderboard::finalize($month,'Reviewed competition fixture');$snapshot=DB::row('monthly_results',$id);$entries=json_decode($snapshot['entries'],true);competition_check(count($entries),6,'Six available category award slots');competition_check(count(array_unique(array_column($entries,'user_id'))),6,'Maximum one monthly award per member');Leaderboard::publish($id,'Approved test snapshot');competition_check(count(Leaderboard::winners($month)),6,'Consenting winner archive published');$historical=Leaderboard::live($month,'regular',100);$count=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.DB::table('reward_assignments').' WHERE slot LIKE %s','monthly:'.$month.':%'));$corrected=Leaderboard::finalize($month,'Audited correction version with unchanged winners');Leaderboard::publish($corrected,'Reviewed correction');competition_check((int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.DB::table('reward_assignments').' WHERE slot LIKE %s','monthly:'.$month.':%')),$count,'Unchanged correction does not duplicate prizes');competition_check(DB::row('monthly_results',$id)['digest'],$snapshot['digest'],'Prior published snapshot remains immutable');competition_check(Leaderboard::live($month,'regular',100),$historical,'Historical leaderboard uses immutable published ranking');
// Native WooCommerce prize coupons remain tied to WordPress user IDs after email changes.
$def=Rewards::definition(array('name'=>'Product voucher','type'=>'coupon','stock'=>1,'config'=>array('value'=>5000)));$campaign=Rewards::campaign(array('name'=>$run.'voucher','month'=>wp_date('Y-m'),'category'=>'manual','definition_id'=>$def,'capacity'=>1));$box=Rewards::assign($users[0],$campaign,$run.'voucher');Rewards::transition($users[0],$box,'open');$claimed=Rewards::transition($users[0],$box,'claim');$coupon=new WC_Coupon($claimed['coupon']);competition_check((int)$coupon->get_meta('_ghr_owner'),$users[0],'Prize coupon immutable owner ID');wp_update_user(array('ID'=>$users[0],'user_email'=>$run.'changed@example.org'));competition_check($coupon->get_email_restrictions(),array(),'Prize coupon does not bind to mutable email');wp_set_current_user($users[0]);$denied=false;try{apply_filters('woocommerce_coupon_is_valid',true,$coupon,new WC_Discounts());}catch(Exception $e){$denied=true;}competition_check($denied,true,'Changed email requires reverification before prize redemption');DB::update(DB::table('memberships'),array('email_verified_at'=>DB::now()),array('user_id'=>$users[0]));competition_check(apply_filters('woocommerce_coupon_is_valid',true,$coupon,new WC_Discounts()),true,'Owner coupon remains valid after email change');wp_set_current_user($users[1]);$denied=false;try{apply_filters('woocommerce_coupon_is_valid',true,$coupon,new WC_Discounts());}catch(Exception $e){$denied=true;}competition_check($denied,true,'Other members cannot use prize coupon');
echo "COMPETITION PASS: $ghr_competition_count assertions\n";
}finally{update_option('ghr_settings',$before,false);}
